function catalogCard(item){
 const href=item.url||STORE;
 const isPdf=Boolean(QUICK_PDF_DETAIL[item.id]);const internalExtra=item.id==='dinofree'?'/free/dino-day1':item.id==='best5'?'/sets/best5':null;
 const action=isPdf?'실제 활동지 미리보기 →':internalExtra?'상세 안내 보기 →':'크티에서 상품 확인하기 ↗';
 const internal=isPdf?`/worksheets/${item.id}/`:internalExtra?internalExtra+'/':href;
 const more=(isPdf||internalExtra)?`<a class="catalog-store-small" href="${href}" target="_blank" rel="noopener noreferrer" aria-label="${item.name} 크티 상품 페이지 바로가기">크티 바로가기 ↗</a>`:'';
 return `<article class="catalog-card" data-category="${item.category}" data-name="${item.name} ${item.short}">
 <a class="catalog-visual" href="${internal}" ${(isPdf||internalExtra)?'':'target="_blank" rel="noopener noreferrer"'} aria-label="${item.name} ${action}"><img src="${catalogImg(item)}" alt="${item.name} ${item.asset_status==='pdf_preview'?'PDF 원본 기반 미리보기':'크티 목록 썸네일'}" loading="lazy"></a>
 <div class="catalog-data"><span class="catalog-type">✦ ${item.tag}</span><h3>${item.name}</h3><p>${item.short}</p>
 <a class="catalog-card-action" href="${internal}" ${(isPdf||internalExtra)?'':'target="_blank" rel="noopener noreferrer"'}><span>${action}</span><span aria-hidden="true">↗</span></a>${more}</div></article>`;
}
