function quickDetailPage(id){
 const d=QUICK_PDF_DETAIL[id]; if(!d){catalogPage('worksheets');return;}
 const free=id==='autumnfree';
 const back=free?'/free':'/worksheets';
 const crumbs=free?'무료 공개 이력 활동지':'간편 활동지';
 const thumbs=d.images.map((img,i)=>`<button class="quick-thumb ${i===0?'active':''}" type="button" data-quick-thumb="${i}" aria-label="미리보기 ${i+1} 선택"><img src="${img}" alt="${d.title} 미리보기 ${i+1}"></button>`).join('');
 app.innerHTML=`<div class="wrap breadcrumbs"><a href="/">HOME</a> › <a href="${back}">${crumbs}</a> › ${d.title}</div>
 <section class="quick-detail-hero" style="--quick-accent:${d.color}"><div class="wrap quick-detail-grid"><div class="quick-detail-gallery">
 <div class="quick-main-frame"><img id="quick-main-img" src="${d.images[0]}" alt="${d.title} PDF 실제 페이지 미리보기" data-lightbox="${d.images[0]}"><span class="quick-preview-label">실제 PDF 미리보기 · 워터마크</span></div>
 <div class="quick-thumbs">${thumbs}</div></div>
 <div class="quick-detail-copy"><span class="quick-kicker">IZZYON · ${d.type}</span><div class="eyebrow" style="margin-top:17px">${d.tag}</div>
 <h1>${d.title}</h1><p class="quick-subtitle">${d.subtitle}</p>
 <div class="quick-facts"><div><b>파일 구성</b><span>A4 PDF · ${d.countLabel||d.count+"페이지"}</span></div><div><b>활동 유형</b><span>${d.tag}</span></div><div><b>미리보기</b><span>원본 파일이 아닌 워터마크 이미지</span></div></div>
 <a class="btn primary quick-buy" href="${d.url}" target="_blank" rel="noopener noreferrer">크티에서 상품 확인하기 ↗</a>
 ${d.previewNote?`<p class="quick-note" style="border-top:0;padding-top:0">${d.previewNote}</p>`:""}<a class="quick-back-link" href="${back}">← ${crumbs} 목록으로 돌아가기</a>
 <p class="quick-note">구매 가격, 할인 및 파일 제공 조건은 크티 상품 페이지에서 확인해 주세요. 홈페이지에서 직접 결제하지 않습니다.</p></div></div></section>
 <section class="section quick-details-section"><div class="wrap"><div class="eyebrow">WHAT'S INSIDE</div><h2 class="section-title">이런 놀이를 할 수 있어요</h2><div class="quick-feature-grid">${d.features.map((f,i)=>`<article class="quick-feature"><span>0${i+1}</span><h3>${f}</h3></article>`).join('')}</div><div class="quick-scope"><b>실제 PDF 구성</b><p>${d.groups}</p></div></div></section>
 <section class="section soft quick-preview-section"><div class="wrap"><div class="eyebrow">REAL WORKSHEETS</div><h2 class="section-title">활동지 실제 페이지 미리보기</h2><p class="lead">첨부된 상품 PDF에서 추출한 이미지입니다. 클릭하면 크게 볼 수 있습니다.</p>
 <div class="quick-preview-grid">${d.images.map((img,i)=>`<button type="button" class="quick-preview-card" data-lightbox="${img}" aria-label="${d.title} 미리보기 ${i+1} 확대"><img src="${img}" alt="${d.title} 미리보기 ${i+1}" loading="lazy"><span>미리보기 ${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div></div></section>
 <section class="section"><div class="wrap"><div class="quick-outro"><span>IZZYON PLAY PAPER</span><h2>필요한 놀이를 골라 바로 시작해요.</h2><p>${d.title}의 전체 PDF와 이용 안내는 크티 상품 페이지에서 확인할 수 있어요.</p><a class="btn primary" href="${d.url}" target="_blank" rel="noopener noreferrer">크티 상품 페이지 보기 ↗</a></div></div></section>`;
}
function filterCatalog(){
 const area=document.getElementById('catalog-results');if(!area)return;
 const key=document.querySelector('.catalog-filter.active')?.dataset.catalogFilter||'all';
 const q=(document.getElementById('catalog-search')?.value||'').trim().toLocaleLowerCase();
 const matches=QUICK_CATALOG.filter(item=>(key==='all'||item.category===key)&&(`${item.name} ${item.short}`).toLocaleLowerCase().includes(q));
 area.innerHTML=matches.map(catalogCard).join('');
 const empty=document.getElementById('catalog-empty');if(empty)empty.hidden=matches.length!==0;
}

